import{_ as a}from"./chunks/sh1.DiUu_JVG.js";import{_ as t,c as o,o as l,ae as n}from"./chunks/framework.BrQRMotl.js";const g=JSON.parse('{"title":"Extended Note Block の基礎","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/extended_note_block.md","filePath":"ja/manual/extended_note_block.md"}'),r={name:"ja/manual/extended_note_block.md"};function i(d,e,s,c,u,h){return l(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="extended-note-block-の基礎" tabindex="-1">Extended Note Block の基礎 <a class="header-anchor" href="#extended-note-block-の基礎" aria-label="Permalink to &quot;Extended Note Block の基礎&quot;">​</a></h1><p><strong>Extended Note Block</strong> はこの MOD の核となるブロックです。バニラの音符ブロックと比較して、より精密な制御と豊富な機能を提供します。</p><h2 id="設置と基本設定" tabindex="-1">設置と基本設定 <a class="header-anchor" href="#設置と基本設定" aria-label="Permalink to &quot;設置と基本設定&quot;">​</a></h2><ul><li><strong>設置</strong>: バニラの音符ブロックと同様に <strong>Extended Note Block</strong> を設置します。</li><li><strong>インターフェースを開く</strong>: ブロックを <strong>右クリック</strong> すると設定画面が開きます。</li></ul><p><img src="'+a+'" alt="Extended Note Block GUI"></p><h2 id="パラメータの詳細" tabindex="-1">パラメータの詳細 <a class="header-anchor" href="#パラメータの詳細" aria-label="Permalink to &quot;パラメータの詳細&quot;">​</a></h2><p>基本設定画面では、以下のパラメータを設定できます：</p><h3 id="_1-音程-note" tabindex="-1">1. 音程 (Note) <a class="header-anchor" href="#_1-音程-note" aria-label="Permalink to &quot;1. 音程 (Note)&quot;">​</a></h3><ul><li><strong>範囲</strong>: 0 - 127 (MIDI 規格に対応)。</li><li>バニラの 0-24 の制限とは異なり、ここでは10オクターブにわたる音を再生できます。</li></ul><h3 id="_2-力度-velocity" tabindex="-1">2. 力度 (Velocity) <a class="header-anchor" href="#_2-力度-velocity" aria-label="Permalink to &quot;2. 力度 (Velocity)&quot;">​</a></h3><ul><li><strong>範囲</strong>: 0 - 127。</li><li>音の大きさ（音量）を制御します。</li></ul><h3 id="_3-持続音-sustain" tabindex="-1">3. 持続音 (Sustain) <a class="header-anchor" href="#_3-持続音-sustain" aria-label="Permalink to &quot;3. 持続音 (Sustain)&quot;">​</a></h3><ul><li><strong>単位</strong>: Tick (1/20秒)。</li><li>音波が終了するまでの持続時間を制御します。</li></ul><h3 id="_4-再生遅延-delay" tabindex="-1">4. 再生遅延 (Delay) <a class="header-anchor" href="#_4-再生遅延-delay" aria-label="Permalink to &quot;4. 再生遅延 (Delay)&quot;">​</a></h3><ul><li><strong>単位</strong>: ミリ秒 (ms)。</li><li>これは <strong>リアルタイム遅延</strong> 設定です。レッドストーン信号でブロックが起動されると、指定されたミリ秒数だけ待機してから発音します。</li><li>これにより、レッドストーンリピーター（0.1秒単位）よりも細かい音楽的なタイミング調整が可能になります。</li></ul><h3 id="_5-フェードイン-アウト-fade-in-out" tabindex="-1">5. フェードイン/アウト (Fade In/Out) <a class="header-anchor" href="#_5-フェードイン-アウト-fade-in-out" aria-label="Permalink to &quot;5. フェードイン/アウト (Fade In/Out)&quot;">​</a></h3><ul><li><strong>単位</strong>: Tick。</li><li>音を滑らかに出現または消失させ、不自然な途切れ方を防ぎます。</li></ul>',17)])])}const k=t(r,[["render",i]]);export{g as __pageData,k as default};
